    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Je authenticatiebeleid blijft gelden: wachtwoordsterkte, controle op gelekte wachtwoorden, e-mailbevestiging, frequentielimieten en botcontroles.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Je endpoint wordt tijdens een bewerking aangeroepen en het antwoord verandert de uitkomst, bijvoorbeeld door gegevens aan een token toe te voegen of aanmelding te weigeren.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Je endpoints ontvangen een ondertekend bericht na een gebeurtenis hier, zodat je systemen kunnen reageren zonder ons voortdurend te bevragen.',
    'your_hr_system_people_get_an_account_on_their_start_dat_6be42da6' => 'Je HR-systeem: mensen krijgen op hun eerste werkdag een account en verliezen de toegang na hun laatste dag.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'De naam, domeinen en standaardinstellingen van je organisatie. Wijzigingen gelden voor iedereen die zich via deze organisatie aanmeldt.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Je eigen API. Je kiest per scope of apps die door organisaties zijn geregistreerd deze mogen aanvragen.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Je eigen inloggegevens bij elke provider, aangeboden op alle aanmeldpagina’s van deze omgeving. Elke organisatie erft ze.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Je eigen inloggegevens bij elke provider, beschikbaar voor iedereen in deze omgeving. Elke organisatie erft ze.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Je ontvanger behoudt hetzelfde geheim en gebruikt het ongewijzigd, inclusief het whsec_-prefix, als HMAC-sleutel voor X-Cbox-Signature.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Je aanmeldpagina draagt je logo en kleuren. Mensen voeren er hun wachtwoord in, dus de pagina moet duidelijk herkenbaar van jou zijn.',
    'your_workspace_its_projects_team_keys_and_billing_sign_d55c648f' => 'Je werkruimte met projecten, team, sleutels en facturering. Aanmelding bij je apps wordt ingesteld in de console van elke omgeving.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Een functievlag is een instelling die je apps voor een persoon in een organisatie opvragen. Schakel de vlag in voor bepaalde gebruikers, organisaties of een percentage van iedereen. Elke app krijgt hetzelfde antwoord via de claim `feature_flags` in het token of het evaluatie-endpoint, zonder nieuwe deployment. Een gebruikersregel gaat boven een organisatieregel, vervolgens boven de uitrol en dan boven de standaardwaarde.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Met een sleutel kunnen je scripts en integraties namens jou de API van een app aanroepen zonder aanmelding. De sleutel kan alleen doen wat jij in die app mag. Als jouw toegang wordt beperkt, verliest de sleutel dezelfde rechten. De sleutel wordt één keer getoond: kopieer hem bij het aanmaken en trek hem meteen in als hij uitlekt of niet meer wordt gebruikt.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Een machtiging staat een rol één handeling toe, zoals facturen maken of rapporten lezen. Je kunt hier zonder code eigen machtigingen definiëren en samenvoegen tot rollen. Apps kunnen hun machtigingen ook automatisch registreren, zodat de lijst overeenkomt met de werkelijke controles. Je eigen machtigingen kun je wijzigen; gedeelde machtigingen van de omgeving mag je gebruiken maar niet aanpassen.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Een telefoon met de authenticator-app beantwoordt goedkeuringsverzoeken en meldt aanmeldingen namens jou. Registreer de telefoon door de code te scannen. Verwijder hem hier direct als je hem kwijtraakt; hij kan dan niets meer goedkeuren.',
    'a_project_is_one_idp_product_this_workspace_owns_and_it_a5e40dff' => 'Een project is een identiteitsproviderproduct van deze werkruimte en bevat de bijbehorende omgevingen. Totdat de werkruimte in haar eigen console een project maakt, valt hier niets te selecteren of te openen. Dit scherm maakt geen project namens de werkruimte.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Een project is een van je producten met een eigen abonnement, aanmelding en omgevingen zoals productie en staging. Open hier een omgeving om deze te beheren. Maak een nieuw project als je een product lanceert dat apart moet worden beheerd en gefactureerd.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Een rol is een functie die je apps begrijpen, zoals redacteur of supportmedewerker. Je wijst hier rollen toe en elke app bepaalt wat haar rollen mogen doen. Rollen volgen de persoon naar alle gekoppelde apps, zodat je toegang op één plek kunt geven en intrekken.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Een beoordeling laat je controleren wie welke rol heeft en of die nog nodig is. Toegang stapelt zich op als mensen van team wisselen en oude machtigingen houden. Een beoordeling helpt die op te ruimen. Intrekkingen worden bij het sluiten toegepast en de hele ronde wordt vastgelegd voor je auditor.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Een schema beschrijft hoe gebeurtenissen van een actie eruit moeten zien: de doeltypen en metadata. Gebeurtenissen met een schema worden bij binnenkomst gecontroleerd. Zonder schema worden ze ongewijzigd geaccepteerd, tenzij de strikte modus aanstaat.',
    'a_workspace_is_one_signed_up_company_s_home_on_this_ins_3053f712' => 'Een werkruimte is de plek van een geregistreerd bedrijf op deze installatie, met projecten, omgevingen en team. Open haar om die te beheren. Schorsen meldt de leden af en stopt aanmeldingen in alle bijbehorende omgevingen.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Toegang stapelt zich op. Mensen wisselen van team en houden oude rechten totdat een auditor ernaar vraagt. Een beoordeling legt de huidige toewijzingen vast en laat iemand voor elke toewijzing beslissen of die nog nodig is.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Voeg de persoon hieronder toe aan een organisatie om daar toegang te geven. Als je apps geen eigen klantomgevingen hebben, kun je een beheer- en supportrol voor de hele omgeving toewijzen.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Een beheer- en supportrol geef je aan eigen medewerkers, zoals support en operations, voor de hele omgeving. De rol geldt in elke organisatie en kan niet door haar beheerders worden gezien, toegewezen of verwijderd. Een op deze manier toegewezen approl blijft beperkt tot die app.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Een beheer- en supportrol geef je aan eigen medewerkers voor de hele omgeving. De rol geldt in elke organisatie en kan niet door haar beheerders worden gezien of gewijzigd.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Een agent is software die met een beheersleutel in deze omgeving werkt: een AI-assistent zoals Claude Code of Cursor, een interne bot of je backend. Geef elke agent een eigen sleutel met alleen de benodigde scopes. Kies welke acties je goedkeuring nodig hebben en trek de sleutel direct in als het werk klaar is of iets verdacht lijkt.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Een API is een dienst van jou die toegangstokens ontvangt, zoals https://api.example.com. Registreer de API met de scopes die hij herkent. Jij bepaalt welke scopes apps van organisaties mogen aanvragen. Een token voor de API bevat het adres als doelgroep, die je dienst controleert.',
    'an_environment_is_a_fully_isolated_identity_service_wit_fed9a3d8' => 'Een omgeving is een volledig geïsoleerde identiteitsdienst met eigen gebruikers, sleutels, aanmelding en uitgever. Hier staan alle omgevingen van de installatie met hun werkruimte. Maak een omgeving, selecteer haar in de console en stel de eerste organisatie en beheerder in.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Een omgeving is volledig geïsoleerd, met eigen gebruikers, sleutels, aanmelding en uitgever. Maak hierboven de eerste en stel daarna een organisatie en beheerder in.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Een identiteitsprovider die serviceprovidermetadata importeert, gebruikt deze URL in plaats van een aparte entiteits-ID en ACS-URL. De URL werkt al voordat de gegevens van de identiteitsprovider zijn ingevuld.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Een organisatie groepeert gebruikers, aanmeldmethoden en rollen. Maak er hierboven een of stel de eerste organisatie en beheerder in via het scherm Omgevingen.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'De eigen provider van een organisatie vervangt die van de omgeving op haar aanmeldpagina. Ook uitgeschakelde geërfde providers staan in de lijst. Uitschakelen verwijdert alleen de knop; verplicht SSO voorkomt andere aanmeldmethoden.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'API-sleutels en tokens voor andere diensten die je apps en agents nodig hebben, worden hier versleuteld opgeslagen in plaats van in elke appconfiguratie. Voeg een geheim één keer toe en geef bepaalde apps gebruiksrecht. Het wordt niet opnieuw getoond; vernieuw het als je het kwijtraakt.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API-sleutels die je apps en agents bij andere diensten gebruiken. Elke waarde wordt versleuteld opgeslagen, alleen aan bevoegde apps gegeven en na het opslaan niet meer getoond.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Apps die namens een van je gebruikers willen handelen. Elke gebruiker keurt de eigen verzoeken goed. Wijs hier alleen verzoeken af die misbruik lijken; de afwijzing komt in het auditlogboek.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Apps met eigen gebruikerslijsten raken uit de pas zodra iemand toetreedt of vertrekt. Een SCIM-verbinding geeft elke wijziging direct door, ook vertrek, wat anders makkelijk wordt vergeten.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID stuurt een ondertekend bericht naar je endpoint na een gebeurtenis, zoals een nieuw lid of een rolwijziging. Zo reageren je systemen zonder voortdurend te pollen. Afleveringen worden zo nodig herhaald. Het endpoint wordt achteraf geïnformeerd en kan de gebeurtenis niet tegenhouden.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Bevestig toegang die nog nodig is en trek de rest in. Niets wordt toegepast voordat de beoordeling sluit. Een ingetrokken beheer- en supportrol verdwijnt dan in alle organisaties tegelijk.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Kies SCIM als je provider gegevens naar ons stuurt, Google Workspace of Entra als wij ze moeten ophalen, of je HR-systeem zoals Workday, BambooHR, Rippling, HiBob of Personio, zodat accounts op de startdatum worden gemaakt.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code opent je browser om je hier aan te melden en vraagt wat je wilt toestaan. Je hoeft geen sleutel te bewaren. Elke MCP-client met OAuth-aanmelding werkt op dezelfde manier met deze URL.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Scheid waarden met komma’s of spaties. Een ingevoerde scope heeft geen API-eigenaar en komt ongewijzigd in de tokens van de app. De scope kan nooit een geregistreerde API als doelgroep aangeven; gebruik daarvoor de lijsten hierboven.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'SSO-verbindingen maken, wijzigen, in- en uitschakelen en verwijderen, SSO verplicht stellen voor een organisatie en haar e-maildomeinen verifiëren en via SSO routeren. Verandert hoe mensen zich aanmelden.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Maakt de organisatie, eigenaar, het eerste product en de productieomgeving van dat product. De eigenaar krijgt per e-mail een link om een eigen wachtwoord in te stellen; jij kiest dat niet voor die persoon.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Schema’s voor validatie van auditgebeurtenissen definiëren, vervangen en verwijderen en de bewaartermijn wijzigen. Een kortere termijn verwijdert oudere gebeurtenissen definitief.',
    'deleting_this_workspace_tears_down_every_project_and_en_f26b2e2f' => 'Deze werkruimte verwijderen verwijdert alle bijbehorende projecten en omgevingen. Om actieve identiteitsproviders te beschermen, kan dit niet via zelfservice. Neem contact op met support om verder te gaan.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Elke organisatie is een bedrijf of team dat je product gebruikt, met eigen leden, rollen, domeinen en SSO. Maak er een voor elk bedrijf dat zich registreert. Open de organisatie om leden, uitnodigingen en geverifieerde domeinen te beheren of haar te schorsen.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Elke pipeline laat mensen hun eigen account bij een dienst zoals GitHub, Google of Slack koppelen. De tokens worden hier versleuteld bewaard en actueel gehouden. Bevoegde apps vragen een geldig token op wanneer ze de dienst namens de persoon aanroepen en slaan zelf geen token op.',
    'each_project_in_your_workspace_has_its_own_plan_and_env_c5ff35b1' => 'Elk project in je werkruimte heeft een eigen abonnement en omgevingslimiet. Hier staan die naast het gebruik van deze maand: organisaties, gefactureerde SSO-verbindingen en aanmeldingen. De prijs telt maandelijks actieve gebruikers en bedrijfsverbindingen zoals SSO en SCIM. Sandboxomgevingen hebben geen verbindingskosten.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'De hele omgeving: iedereen met een account in deze omgeving kan zich bij deze app aanmelden, ongeacht de organisatie. Kies een organisatie als dat niet de bedoeling is.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Een persoon definitief wissen (AVG, artikel 17): inloggegevens, sessies, lidmaatschappen en persoonsgegevens worden verwijderd en het account gepseudonimiseerd. Dit kan niet ongedaan worden gemaakt.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Evaluatievolgorde: blokkeerlijst, toestaanlijst, je regels van bovenaf met de eerste overeenkomst als beslissing, daarna ingebouwde regels waarbij de strengste overeenkomst beslist. Zonder overeenkomst wordt toegang toegestaan.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Elke actie wordt geaccepteerd zoals je app deze verstuurt. Voeg een schema toe om de gebeurtenissen bij binnenkomst te controleren. Een consistent logboek wordt gewaarborgd bij het schrijven, niet pas bij het lezen.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Elke beheerwijziging aan leden, rollen, verbindingen of apps wordt hier direct vastgelegd met wie deze uitvoerde en wanneer. Er hoeft niets te worden ingesteld.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'API-sleutels in appconfiguraties of omgevingsbestanden zijn niet centraal te vernieuwen of snel in te trekken. Hier worden ze versleuteld opgeslagen, per app toegewezen en met één klik ingetrokken.',
    'every_api_key_the_people_in_this_organization_have_crea_15e73625' => 'Alle API-sleutels die mensen in deze organisatie voor haar apps hebben gemaakt. Trek gelekte of ongebruikte sleutels in. Iedereen maakt eigen sleutels onder Mijn account.',
    'every_api_key_the_people_in_this_organization_have_crea_fe7787a7' => 'Alle API-sleutels die mensen in deze organisatie hebben gemaakt: houder, app, machtigingen en laatste gebruik. Een sleutel heeft maximaal de rechten van de houder en werkt niet meer zodra die vertrekt. Trek gelekte of ongebruikte sleutels in. Iedereen maakt eigen sleutels onder Mijn account.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Elke app die mensen via Cbox ID aanmeldt of de API aanroept, wordt hier geregistreerd en krijgt eigen inloggegevens. Registreer er een per app en omgeving. Deel nooit inloggegevens, zodat je er een kunt intrekken zonder de andere apps stil te leggen.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Alle browsers en apparaten waarop je bent aangemeld, apps die namens jou mogen handelen en recente aanmeldingen en beveiligingswijzigingen. Herken je iets niet, meld de sessie dan af of trek de appautorisatie in en wijzig daarna je wachtwoord.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Elke wijziging in deze organisatie: wie wat deed, aan welk onderdeel en wanneer. De items zijn verbonden met een hashketen; wijzigen of verwijderen verbreekt de keten en wordt zichtbaar. Het logboek is bewust alleen leesbaar en vormt het bewijs voor je auditor.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Alle verbindingen tussen Cbox ID en andere systemen op één plek: SSO, sociale aanmelding, directory- en HR-synchronisatie, uitgaande provisioning, SAML-apps, webhooks, hooks, logstreams en pipelines. Elke cataloguskaart opent de juiste instelpagina. Verbindingen toont alle bestaande verbindingen met hun status, fouten eerst.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Alle organisaties in de omgeving die in de console is geselecteerd, als boom van resellers, beheerde organisaties en subeenheden. Maak of schors een organisatie of verplaats haar onder een andere bovenliggende organisatie.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Alle pagina’s die je vanaf nu opent, zoals Organisaties, Gebruik en organisatiedetails, lezen deze omgeving. In geen van beide omgevingen wordt iets gewijzigd.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Alle personen met een identiteit in deze omgeving, ongeacht hun organisaties. Open een persoon om wachtwoord of tweede factor te resetten, sessies te beëindigen, het account te deactiveren, organisaties en rollen te wijzigen of de persoon definitief te wissen na een verwijderverzoek.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Alle intrekkingen in deze beoordeling worden nu toegepast. Onbeoordeelde items volgen het beoordelingsbeleid, dat standaard toegang intrekt. Dit kan niet ongedaan worden gemaakt.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Alle geheimen waarmee deze app nu kan authenticeren. Alleen een hash van elk geheim wordt opgeslagen. De lijst toont de laatste vier tekens om te herkennen welk geheim een deployment gebruikt.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Alle uitgegeven tokens worden nu ingetrokken en nieuwe aanmeldingen kunnen dit niet meer gebruiken. Apps die tokens zelf controleren accepteren ze tot hun vervaldatum, uiterlijk tot het einde van de sessie.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Alle aanmeldmethoden met status en de plek waar je ze wijzigt: wachtwoord, passkeys, e-maillink, sociale aanmelding, Enterprise SSO en tweede factor. De omgeving bepaalt de meeste; organisaties beheren hun eigen SSO-verbindingen. Beperkingen door de deployment staan vermeld met de naam van de instelling.',
    'every_workspace_on_this_install_open_one_to_walk_its_pr_4abbea51' => 'Alle werkruimten van deze installatie. Open er een om producten en omgevingen te beheren. Schorsen meldt leden af en stopt authenticatie in alle bijbehorende omgevingen.',
    'everyone_who_administers_this_workspace_the_built_in_ro_26825e5f' => 'Iedereen die deze werkruimte beheert, hun ingebouwde rol (Eigenaar, Beheerder, Ontwikkelaar, Lid of Lezer) en toegankelijke omgevingen. Nodig mensen per e-mail uit en geef alleen de omgevingen die hun werk vereist.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Iedereen die zich bij deze organisatie kan aanmelden en je nog niet geaccepteerde uitnodigingen. Nodig mensen per e-mail uit: ze stellen hun eigen aanmelding in, zodat je hun wachtwoorden niet hoeft te beheren.',
    'platform_search_summary' => 'Resultaten voor ‘:term’: organisaties: :organizations; gebruikers: :users.',
