    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Een code kan worden gestolen via simswapping of ongeoorloofde nummerportering, onderschept in het telefoonnetwerk of ingevuld op een overtuigende valse aanmeldpagina. Toch is een code veel veiliger dan alleen een wachtwoord. Schakel dit in voor mensen die geen authenticator-app of passkey kunnen gebruiken.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Een logo dat van een andere website werd geladen, liet die website weten wie je aanmeldpagina opende. Daarom tonen gehoste pagina’s nu alleen afbeeldingen die hier zijn geüpload. Upload het hieronder bij :part2 of verwijder het om deze melding te laten verdwijnen.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Een rol is een label in het token. Rollen die een app definieert, zijn hier alleen-lezen; de overige definieer je zelf. Elk lid heeft ook precies één :part2 :part3 :part4 (eigenaar, beheerder, ontwikkelaar, lid of lezer), die bepaalt wat diegene in deze console mag beheren.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '‘:part1’ hoort al bij een andere API in deze omgeving. Een tokenaanvraag noemt een scope alleen bij de sleutel, dus elke sleutel kan maar bij één API horen.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 horen bij een API die deze app niet mag gebruiken. Ze worden uit alle tokens weggelaten; verwijder ze uit de ingevoerde scopes.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 kunnen aanmelden met wachtwoorden of via deze verbinding. Als eenmalige aanmelding verplicht is, worden alle andere aanmeldmethoden geweigerd. Zo kunnen ook al uitgegeven toegangsmiddelen de zojuist ingestelde provider niet omzeilen. De meeste bedrijven die een IdP koppelen, willen dit, maar lees eerst wat het inhoudt.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 heeft nog geen rechten, dus :part2 is :part3 leeg. De rolnaam blijft beschikbaar om te gebruiken.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 is al ingesteld voor deze organisatie. Wijzig de inloggegevens of verwijder eerst de verbinding.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 wordt niet meer aangeboden. Iedereen die ermee heeft aangemeld, behoudt het account en kan nog steeds het wachtwoord gebruiken.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 is uitgeschakeld op alle aanmeldpagina’s. De inloggegevens blijven bewaard, zodat je het weer kunt inschakelen.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 is uitgeschakeld op de aanmeldpagina van deze organisatie. De inloggegevens blijven bewaard, zodat je het weer kunt inschakelen.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 is je enige manier om aan te melden. Stel eerst een wachtwoord in of voeg een passkey toe voordat je de verbinding verbreekt.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 is de eenmalige aanmelding van je organisatie. Zo identificeert je organisatie je, dus deze verbinding kan hier niet worden verbroken.',
    '_part1_its_team_is_administered_under_workspace_team_by_939d535a' => ':part1 Het team wordt beheerd onder Werkruimte › Team door iemand met een werkruimterol, niet vanaf hier.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Er wordt hier nog niets bepaald door :part3. Als je hieronder iets wijzigt, wordt het een eigen regel van deze organisatie.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 bijgewerkt, :part3 gedeprovisioneerd,:part4 :part5 overgeslagen, :part6 groepen :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Werk eerst je ontvanger bij: vanaf de volgende poging weigert die elke levering die niet kan worden geverifieerd.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 weigert de aanmelding als dit niet exact overeenkomt. De waarde blijft voor deze configuratie bewaard, zodat je deze nu in :part2 kunt plakken en daarna hier kunt opslaan.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — sessies, passkeys en tweede factoren, profielen bij identiteitsproviders, directorygegevens, uitgegeven tokens, roltoekenningen en auditgeschiedenis blijven bewaard en kunnen opnieuw worden geactiveerd.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Alles wat je organisatie heeft ingesteld en wat er nog moet gebeuren. De checklist toont de werkelijke status: elke stap wordt automatisch afgevinkt zodra deze is voltooid.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Je volledige merkuitstraling op één pagina: logo, favicon, kleuren, lettertype en hoeken van de gehoste aanmeldpagina met een livevoorbeeld, plus productnaam, e-mailafzender en welkomstmail. Stel dit één keer in voor de hele omgeving, zodat alle organisaties het overnemen. Je kunt een organisatie ook een eigen uitstraling geven op het tabblad Huisstijl.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Vanaf de volgende poging weigeren blokkeringen aanmeldingen en registraties in deze omgeving, en vereisen controles aanvullende verificatie. Een onjuiste regel kan echte mensen buitensluiten.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Geef één aan de mensen die uw apps ondersteunen of uitvoeren. De eigen rol van een app bereikt alleen de tokens van de app; een rol voor alle apps bereikt elk van hen.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Het aantal organisaties, gebruikers, SSO-verbindingen, apps en gebruikerssynchronisaties in deze omgeving, met links naar de bijbehorende pagina’s. Met de snelkoppelingen eronder maak je de meest gebruikte onderdelen aan: een organisatie, een gebruiker, een SSO-verbinding of een app.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Het aantal mensen dat is ingelogd en hoe vaak je apps de API hebben aangeroepen in de afgelopen 30 dagen. Dit overzicht helpt je de belasting te beoordelen en afwijkingen op te merken. Het is geen factuur.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Hoe vaak gegevens worden opgehaald en welke velden uit het HR-systeem voor elke persoon worden overgenomen, zoals kostenplaats of locatie. Als je de velden wijzigt, wordt de volgende synchronisatie volledig uitgevoerd.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Zo worden auditgegevens uit Cbox ID geëxporteerd: een geplande export stuurt elke vijf minuten nieuwe vermeldingen naar je SIEM of archief. Een dagelijkse bewaartaak maakt een controlepunt van het logboek zonder iets te verwijderen. Hier kun je iemands auditgeschiedenis ophalen voor een AVG-inzageverzoek of in de console van een omgeving controleren of de exports worden uitgevoerd.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Als de app later een andere URL opgeeft, vervalt deze goedkeuring en wordt opnieuw om je goedkeuring gevraagd. De bestemming waar wachtwoorden naartoe worden gestuurd, mag niet ongemerkt veranderen. Gedelegeerd aanmelden helpt bij de overstap: zodra nog maar weinig mensen het oude systeem gebruiken, schakel je het uit en stuur je hen een link om hun wachtwoord opnieuw in te stellen.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'De knop verdwijnt en de inloggegevens worden verwijderd. Iedereen die deze verbinding heeft gebruikt, behoudt het account en kan nog steeds het wachtwoord gebruiken. Schakel de verbinding in plaats daarvan uit als je de inloggegevens wilt bewaren.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'De bijbehorende scopes worden ook verwijderd. Apps die ze hadden, behouden ze als ingevoerde scopes die geen toegang meer geven tot deze API. Al uitgegeven tokens blijven werken tot ze verlopen.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Sleutels voor de beheer-API van een omgeving: beheer de organisaties, leden, uitnodigingen, rollen en apps van één omgeving vanuit je eigen backend. Elke sleutel heeft expliciet vastgelegde scopes.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Sleutels die de gebruikers van deze organisatie voor haar apps hebben aangemaakt, met de rechten van elke sleutel. Gebruikers maken hun eigen sleutels aan. Trek sleutels in die zijn uitgelekt of niet meer worden gebruikt.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Laat dit veld bij vrijwel alle providers leeg. Hun ID-tokens worden gecontroleerd met de ondertekeningssleutels uit hun discovery-document (jwks_uri), ook na sleutelrotaties. Plak de openbare PEM-sleutel van de provider alleen als deze geen sleutels publiceert.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Laat mensen aanmelden met een account dat ze al hebben. Stel een provider één keer in voor de omgeving, zodat alle organisaties deze aanbieden. Een organisatie kan in plaats daarvan eigen inloggegevens gebruiken of een provider uitschakelen.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Laat de gebruikers van je apps hun eigen GitHub-, Google-, Slack- of Salesforce-account koppelen, zodat je apps die API’s namens hen kunnen aanroepen. Hun tokens worden versleuteld opgeslagen, hier vernieuwd en alleen tijdelijk beschikbaar gesteld aan de apps die je toestemming geeft.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Laat je gebruikers aanmelden met hun bestaande bedrijfsaccount bij Microsoft Entra ID, Okta of Google Workspace, in plaats van met een apart wachtwoord hier. Je koppelt je identiteitsprovider één keer en verifieert je e-maildomeinen. Iedereen met een van die domeinen wordt daarna naar je provider gestuurd om aan te melden.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Aanmelden met Entra ID, Okta of Google Workspace is beschikbaar in het Enterprise-abonnement. Neem contact op met je accountteam om dit voor deze organisatie in te schakelen.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Nog geldige links die aan de IT-beheerder van deze organisatie zijn verstrekt. Als je een link intrekt, werkt deze direct niet meer. Instellingen die al via de link zijn gemaakt, blijven behouden.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Zoekt een organisatie op naam of korte identificatie, of een gebruiker op naam of e-mailadres, in alle omgevingen van deze installatie en niet alleen de omgeving die de console toont. Gebruik dit als iemand hulp vraagt en je niet weet in welke omgeving die persoon zit.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Metadataschema’s gebruiken een deelverzameling van JSON Schema: een object met eigenschappen van het type tekenreeks, getal, geheel getal, boolean of null, met regels voor toegestane waarden, lengte, bereik, patroon en formaat. Elke opgeslagen wijziging maakt een nieuwe versie. Al vastgelegde gebeurtenissen behouden de versie waarmee ze zijn gevalideerd.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Stuurt elke nieuwe auditlogvermelding direct door naar de tools van je beveiligingsteam, zoals een SIEM. Stel dit in zodat onderzoeken kunnen beginnen in de tools die je team al gebruikt, zonder eerst een export op te vragen. Levering vindt minstens één keer plaats, dus af en toe kunnen duplicaten voorkomen.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Voor de meeste integraties zijn webhooks geschikter: ze worden na de gebeurtenis uitgevoerd en kunnen het proces niet tegenhouden. Gebruik een hook alleen als je eigen systeem moet kunnen ingrijpen tijdens een aanmelding of het uitgeven van een token.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Er wordt geen nieuw geheim uitgegeven. Vanaf de volgende poging, inclusief herhaalde pogingen, gebruiken leveringen de headers van de andere methode. Een ontvanger die niet is bijgewerkt, weigert dan elke levering.',
    'nobody_is_on_this_workspace_it_has_no_owner_so_nobody_c_554101fb' => 'Deze werkruimte heeft geen leden en geen eigenaar, dus niemand kan aanmelden om haar te beheren. Dit wijst op een fout bij het aanmaken die moet worden onderzocht, niet alleen op een lege lijst.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Er zijn geen vermeldingen die altijd worden geweigerd of van de regels zijn uitgezonderd. Blokkeer een adresbereik waarvan aanvallen afkomstig zijn, of zonder je kantoornetwerk uit van de regels voor aanmeldfrequentie.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Toont Google, GitHub, Apple en andere providers als knoppen op je aanmeldpagina voor mensen die liever een bestaand account gebruiken dan nog een wachtwoord maken. Stel een provider één keer in voor de omgeving, zodat alle organisaties deze aanbieden. Een organisatie kan eigen inloggegevens gebruiken of een provider uitschakelen. Je levert de inloggegevens aan; de rest wordt automatisch ingevuld. Een e-mailadres dat een provider doorgeeft, is op zichzelf nooit voldoende om hier toegang te krijgen tot een bestaand account.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Ingeschakeld voor dit percentage van de personen waarop de bovenstaande regels niet van toepassing zijn. Een stabiele hash van de gebruikers-ID selecteert telkens dezelfde personen; een verhoging voegt alleen mensen toe. Laat dit leeg als je geen geleidelijke uitrol wilt.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Eén gemarkeerde gebeurtenis (siem.stream.test) wordt nu verzonden met de instellingen en inloggegevens van deze stream, zonder wachtrij of herhaalde poging. Bij succes verdwijnt ook de melding ‘Actie vereist’.',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'Eén vermelding per regel, inclusief protocol, bijvoorbeeld https://app.example.com. Als een regel ongeldig is, wordt de hele lijst geweigerd. Ongeldige regels worden niet ongemerkt weggelaten.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'Eén `type` per resourcetype, met de bijbehorende `relation`-vermeldingen eronder. Een relatie wordt bepaald door de subjecten die een tuple rechtstreeks noemt ([user, group#member]), een andere relatie (owner), een relatie op een bovenliggende resource (viewer from parent) of een combinatie met or, and of but not.',
    'one_workspace_on_this_install_its_team_its_projects_and_e343ed1c' => 'Eén werkruimte in deze installatie, met het team, de projecten en alle omgevingen van die projecten. Als je de werkruimte opschort, worden de leden afgemeld en stopt authenticatie in al die omgevingen.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Alleen voor een provider die geen ondertekeningssleutels (jwks_uri) publiceert in het discovery-document. Anders worden de sleutels daar opgehaald, ook na rotaties. Geef een openbare PEM-sleutel op. Deze wordt versleuteld opgeslagen en nooit meer getoond. Laat dit leeg om de huidige sleutel te behouden.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Alleen actieve leden van de gekozen organisatie kunnen aanmelden bij deze applicatie. Alle anderen worden geweigerd en die weigering wordt in het auditlogboek vastgelegd.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Organisatiegegevens in de doelomgeving: leden, SSO, domeinen, toegekende rechten en recente activiteit. Op deze pagina kan alleen de status van de organisatie worden gewijzigd.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organisaties, gebruikers en actieve sessies in alle omgevingen van deze installatie, plus de organisaties met de meeste leden. Deze weergave leest alleen gegevens en verandert nooit de omgeving die in de console is geselecteerd.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Kies het framework waarmee je bouwt. Er wordt een app aangemaakt met een omleiding naar je lokale ontwikkelserver, omgevingsvariabelen om te kopiëren en de code voor aanmelden. De pagina wacht totdat iemand daadwerkelijk aanmeldt. Daaronder staan de stappen om er een product van te maken: huisstijl, organisaties, SSO, een agent, een collega en productie. Elke stap wordt automatisch afgevinkt op basis van de werkelijke toestand van de omgeving, nooit met de hand.',
    'platform_operators_administer_every_workspace_and_envir_fb24c050' => 'Platformoperators beheren alle werkruimtes en omgevingen van deze installatie op een overkoepelend niveau. Voeg alleen iemand als operator toe die de installatie zelf beheert, en schort de toegang op zodra dat niet langer diens taak is.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Koppel een identiteitsprovider aan ons SCIM-endpoint, koppel Google Workspace of Microsoft Entra, of sluit je HR-systeem aan: Workday, BambooHR, Rippling, HiBob of Personio. We halen de persoonsgegevens volgens een schema op uit de gekoppelde systemen.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Verifieer welke e-maildomeinen je organisatie bezit. Een geverifieerd domein kan iedereen met een adres op dat domein rechtstreeks naar je zakelijke SSO-verbinding sturen.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar beoordeelt elke aanmelding en registratie op pogingen met gestolen inloggegevens, botachtige snelheid, geografisch onmogelijke verplaatsingen, nieuwe apparaten, anonimiserende netwerken en wegwerpadressen, plus je eigen regels en toestemmings- en blokkeerlijsten. Elke beslissing wordt vastgelegd. Zodra je handhaving inschakelt, blokkeert Radar toegang of vraagt het om een tweede factor. Bekijk hier de beslissingen voordat je handhaving inschakelt en wanneer iemand meldt niet te kunnen aanmelden.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar beoordeelt elke aanmelding en registratie op pogingen met gestolen inloggegevens, botachtige snelheid, geografisch onmogelijke verplaatsingen, nieuwe apparaten, anonimiserende netwerken en wegwerpadressen, plus je eigen regels en lijsten. De redenen voor elke beslissing worden vastgelegd.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Wachtwoorden weigeren die voorkomen in bekende datalekken. De controle gebruikt Have I Been Pwned zonder het wachtwoord ooit te versturen. Als de dienst niet bereikbaar is, wordt registratie toegestaan in plaats van geblokkeerd.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registreert applicaties die deze omgeving als SAML-identiteitsprovider accepteren. Hun gebruikers melden aan met de accounts die ze hier al hebben. Koppel elke applicatie aan de bijbehorende organisatie, zodat alleen leden daarvan kunnen aanmelden. Zonder koppeling is de applicatie toegankelijk voor iedereen in de omgeving. Dit is de uitgaande richting. Gebruik zakelijke SSO onder Authenticatie voor aanmelding met een extern bedrijfsaccount.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Verzoeken verschijnen hier automatisch wanneer een app of agent je goedkeuring nodig heeft om namens je te handelen. Tot die tijd hoef je niets te doen. Weiger verzoeken die je niet zelf hebt gestart.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Verzoeken van agents die namens een gebruiker willen handelen, verschijnen hier zodra ze binnenkomen. Elke gebruiker keurt de eigen verzoeken goed. Op deze pagina kun je verzoeken weigeren die op misbruik lijken.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Op dit moment melden mensen aan met inloggegevens die hier worden bewaard. Koppel je provider zodat ze hun bestaande bedrijfsaccount kunnen gebruiken. Zodra je dat account bij de provider uitschakelt, verliezen ze hier de toegang.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Scopes, afmeld-URI’s, tokeninstellingen en de URL van het rollenmanifest worden ongewijzigd gekopieerd. Geheimen, sleutels en de gebruikers van de app worden niet gekopieerd. Die horen bij de omgeving waarin ze zijn aangemaakt.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Bekijk de app precies zoals een van de gebruikers: je meldt je aan als die persoon, met een opgegeven reden en voor maximaal een uur. De app krijgt je werkelijke identiteit te zien en krijgt geen mogelijkheid om de aanmelding te verlengen. Het auditlogboek van de organisatie legt vast wie dit deed en waarom.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Stuur deze eenmalige link naar degene die je identiteitsprovider instelt. De link verloopt binnenkort en werkt zonder account. Kopieer hem nu; hij wordt maar één keer getoond.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Stuur deze eenmalige link naar degene die de identiteitsprovider van de organisatie beheert, als die hem niet al per e-mail heeft ontvangen. De link werkt zonder account totdat hij verloopt. Kopieer hem nu; hij wordt maar één keer getoond.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Biedt de identiteitseindpunten van een omgeving aan op je eigen domein, zoals login.example.com, in plaats van op het onze. Je bewijst het eigendom met een DNS-TXT-record. Stel dit in als gebruikers bij het aanmelden alleen je eigen adres moeten zien.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Stel dit in als het vertrouwensbeleid van de rol (IAM › Roles › Trust relationships). Het platform kan de rol alleen aannemen als het de externe ID van deze stream opgeeft. Daardoor kan niemand anders op het platform een stream op jouw rol richten.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Aanmeldingen en verzoeken die Cbox ID riskant genoeg heeft beoordeeld om te markeren, met de nieuwste eerst, de score en de redenen ervoor. Bekijk dit na een toename van mislukte aanmeldingen of als iemand een aanmelding meldt die die persoon niet zelf heeft gedaan.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Aanmeldingen, uitgegeven tokens, nieuwe gebruikers en activeringen van tweefactorauthenticatie per dag over de afgelopen 30 dagen, tenzij een andere periode is ingesteld. De pagina blijft leeg totdat de beheerder van de installatie heeft ingesteld waar analysegegevens worden opgeslagen.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Maakt een momentopname van alle beheer- en ondersteuningsrollen in de hele omgeving als items om te bevestigen of in te trekken. Intrekken verwijdert de rol in alle organisaties tegelijk.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Software die met een beheersleutel in deze omgeving werkt, zoals Claude Code, Cursor, een interne bot of je eigen backend. Elk programma heeft alleen de scopes die je hebt toegekend en wacht op je goedkeuring voor de acties die je hebt gekozen.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Sommige rollen mogen nooit aan dezelfde persoon worden toegekend. Wie een betaling aanmaakt, hoort die niet ook goed te keuren. Stel die rolparen hier in. Cbox ID blokkeert nieuwe toekenningen die de regel zouden schenden en laat zien wie beide rollen al heeft.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF en Generic JSON zijn HTTP-ontvangers waarvoor je een URL opgeeft. Datadog, Amazon S3 en Google Cloud Storage gebruiken eigen instellingen.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Begin met het voorbeeld van documenten in mappen: eigenaren, bewerkers en lezers, waarbij de toegangsrechten van een map worden overgenomen door alles erin. Voor tuples en rechtencontroles is eerst een schema nodig.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Functieschakelaars die je apps opvragen voor één persoon in één organisatie. Schakel een functie in voor bepaalde gebruikers, organisaties of een percentage van alle gebruikers. Elke app krijgt hetzelfde antwoord, in het token of via de API.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'Het adres dat tokens voor deze API als audience vermelden en dat je API controleert. Dit kan later niet worden gewijzigd, omdat alle eerder uitgegeven tokens deze waarde bevatten.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'Het verzoek van de agent wordt geweigerd en de agent kan niet namens deze persoon handelen. De weigering wordt in het auditlogboek vastgelegd en kan niet ongedaan worden gemaakt. De agent moet opnieuw een verzoek indienen.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'De auditgebeurtenissen die je app verstuurt over elke organisatie die ze bedient: wie wat in je product deed en wanneer. Ze worden per organisatie in een hashketen bewaard en aan de eigen beheerders getoond. Gebruik dit wanneer een organisatie om een auditlogboek van haar account vraagt. Definieer schema’s om gebeurtenissen consistent te houden.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'De auditgebeurtenissen die je app verstuurt over alle organisaties die ze bedient, met de nieuwste eerst. De gebeurtenissen van elke organisatie vormen een eigen hashketen.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Het auditlogboek staat hier en de tools van je beveiligingsteam staan ergens anders. Een stream stuurt elke nieuwe vermelding direct naar die tools, zodat een onderzoek niet hoeft te beginnen met een verzoek om een CSV-export.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'De knop verdwijnt van de aanmeldpagina van deze organisatie. De eigen provider van de omgeving neemt de plaats niet over. De inloggegevens blijven bewaard, zodat je de verbinding opnieuw kunt inschakelen.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'De bovengrens voor de toegang van deze app. Een beperking geldt vanaf het volgende token. Als een apparaat of agent een scope aanvraagt die je verwijdert, wordt het verzoek geweigerd in plaats van ongemerkt minder rechten te geven.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'De bestemming heeft de instellingen geweigerd, bijvoorbeeld door een ontbrekende bucket of een verkeerde regio of site. Er wordt niets geleverd totdat dit is hersteld. De vermeldingen blijven wachten en worden niet weggegooid.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'De e-maildomeinen van deze organisatie, elk geverifieerd met een DNS-TXT-record. Na verificatie kun je verplichte doorverwijzing inschakelen: iedereen met een adres op dat domein wordt dan naar je zakelijke SSO-verbinding gestuurd in plaats van naar wachtwoordaanmelding. Verifieer daarom alle domeinen waarop je gebruikers adressen hebben voordat je op SSO vertrouwt.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per_42243556' => 'De sleutels waarmee je eigen code Cbox ID aanroept, met een tabblad per type. Met een geheime beheersleutel beheert je backend de organisaties, leden, uitnodigingen, rollen en apps van één omgeving. Een werkruimtesleutel roept de werkruimte-API aan met een ingebouwde rol. Een publiceerbare sleutel gaat in een browserapp en werkt alleen vanaf toegestane origins. Geheime sleutels en werkruimtesleutels worden maar één keer getoond. Kopieer ze bij het aanmaken en trek ze direct in als ze uitlekken.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'De omgekeerde richting: Cbox ID stuurt je gebruikers via SCIM-endpoints naar de andere SaaS-producten van je bedrijf. Je regelt het geven en intrekken van toegang op één plek, in plaats van in een apart beheerpaneel per leverancier.',
    'the_name_of_your_workspace_which_your_projects_environm_3fa3245f' => 'De naam van je werkruimte, waaronder je projecten, omgevingen en team vallen en die overal in de console wordt getoond. Het verwijderen van een werkruimte legt alle bijbehorende aanmeldomgevingen stil. Daarom vraag je dit aan bij ondersteuning en is er geen verwijderknop.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'De wachtwoordregels, accountvergrendeling en vereisten voor tweefactorauthenticatie en SSO die bij elke aanmelding gelden. Voor de hele omgeving bepaal je ook of passkeys en aanmeldlinks worden aangeboden en hoelang sessies duren. De omgeving stelt de basis vast die elke organisatie overneemt. Organisaties kunnen wachtwoord- en tweefactorregels aanscherpen, maar nooit versoepelen.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Je diensten die toegangstokens ontvangen en de scopes die elke dienst bezit. Jij bepaalt wie de scopes van een geregistreerde API krijgt. Niemand kan ze simpelweg bij een app invoeren om toegang tot je API te krijgen.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'De hele omgeving biedt deze provider op elke aanmeldpagina aan. Kies een organisatie om daarvoor een eigen provider in te stellen. Die vervangt dan de provider van de omgeving op de aanmeldpagina van die organisatie.',
    'the_workspace_s_own_keys_for_the_workspace_api_list_pro_d42a9e3f' => 'De eigen sleutels van de werkruimte voor de werkruimte-API: projecten en omgevingen opvragen, omgevingen aanmaken en teamleden opvragen en uitnodigen. Elke sleutel heeft een ingebouwde rol.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'De sessies en tokens van de persoon worden ingetrokken. Passkeys, tweede factoren, lidmaatschappen, roltoekenningen, API-tokens, kluisgeheimen, apparaten en alle opgeslagen kopieën van de persoonsgegevens worden verwijderd. Het account blijft alleen als gepseudonimiseerde, uitgeschakelde vermelding bewaard. Apps die personen hiervandaan synchroniseren, krijgen een verwijderverzoek. Het auditlogboek bewaart de ondoorzichtige ID, niet de naam of het e-mailadres.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Deze hooks worden tijdens een handeling uitgevoerd, niet erna, en hun antwoord verandert de uitkomst. Je endpoint kan informatie aan een token toevoegen of een aanmelding volledig weigeren. Ze grijpen rechtstreeks in het proces in, dus een traag of defect endpoint heeft direct gevolgen voor de persoon die probeert aan te melden.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'De persoon verliest onmiddellijk toegang tot alle platformpagina’s van deze installatie. Bestaande sessies werken vanaf het volgende verzoek niet meer. Je kunt de persoon hier opnieuw activeren.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Dit kan niet ongedaan worden gemaakt. Inloggegevens, lidmaatschappen en persoonsgegevens worden verwijderd en het account wordt gepseudonimiseerd. Draag eerst het eigendom over als deze persoon de enige eigenaar van een organisatie is.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Deze installatie heeft geen Turnstile-sleutels (CBOX_ID_TURNSTILE_SITE_KEY), dus er kan geen Turnstile-controle worden ingeschakeld. Bij een gemarkeerde registratie wordt in plaats daarvan het e-mailadres bevestigd.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Dit endpoint hoort bij de omgeving en wordt voor elke organisatie daarin uitgevoerd. Het wordt hier getoond omdat het bij je aanmeldingen wordt gebruikt. Je operator beheert het.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Deze omgeving biedt naast de REST-API een MCP-server. Koppel er een agent aan met een beheersleutel. Die kan precies doen wat de scopes van de sleutel toestaan, met dezelfde controles, goedkeuringen en hetzelfde auditlogboek als de console.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Deze omgeving biedt naast de REST-API een MCP-server, de standaardinterface waarmee AI-assistenten tools aanroepen. Vul het adres en een beheersleutel in bij Claude Code, Cursor of een andere MCP-client. De agent kan precies doen wat de scopes van de sleutel toestaan, met dezelfde controles en hetzelfde auditlogboek als de console.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Deze gebruiker kan niet meer aanmelden bij een applicatie in deze omgeving. Bestaande sessies werken vanaf het volgende verzoek niet meer. De gegevens blijven bewaard en je kunt de gebruiker op elk moment opnieuw activeren.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Deze gebruiker is eigenaar of beheerder van een organisatie. De identiteit van zulke accounts kan niet worden overgenomen, omdat dat iemand anders blijvende controle over een organisatie zou kunnen geven.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Op dit moment worden mensen hier handmatig toegevoegd en verwijderd. Koppel de directory die je bedrijf al gebruikt, zodat beide automatisch gebeuren, inclusief de verwijderingen die anders makkelijk worden vergeten.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Zolang een API niet is geregistreerd, is een scope alleen tekst bij een app. Iedereen die de app kan bewerken, kan er elke scope aan toekennen. Registreer de API’s die je apps aanroepen zodat hun scopes een eigenaar hebben.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Geverifieerde domeinen sturen mensen naar je eigen identiteitsprovider. Dit hoort bij het Enterprise-abonnement. Neem contact op met je accountteam om het voor deze organisatie in te schakelen.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Door een eigen domein zoals acme.com te verifiëren, herkent Cbox ID je gebruikers aan hun e-mailadres en stuurt ze rechtstreeks naar je provider. Zo hoeft niemand de juiste aanmeldknop te kiezen.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooks, afmeldberichten aan gekoppelde apps, het ophalen van rolupdates en e-mail in de wachtrij worden op de achtergrond door queueworkers verwerkt, zonder de gebruiker te laten wachten. Als er geen worker draait, wordt niets hiervan verwerkt, terwijl de rest van de console normaal lijkt. Op deze pagina zie je het probleem.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'De acties waarvoor agents in deze omgeving op goedkeuring wachten. Als de sleutel goedkeuring vereist, stopt de agent en vraagt het aan degene die de sleutel heeft aangemaakt. Die persoon kan op de telefoon of hier antwoorden. Iedereen die de omgeving beheert, kan verdachte verzoeken weigeren. Daaronder staan verzoeken van apps om namens een gebruiker te handelen; elke gebruiker keurt de eigen verzoeken goed.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Wat een app bij deze API mag doen. Je eigen apps kunnen alle scopes krijgen. Apps die een organisatie registreert, kunnen alleen scopes krijgen die voor organisaties zijn opengesteld.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'De acties waarvoor software in deze omgeving op goedkeuring wacht. Een agent waarvan de sleutel goedkeuring vereist, stopt en vraagt het aan degene die de sleutel heeft aangemaakt. Antwoord hier of op je telefoon.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'De sleutel die je code opvraagt en die de claim feature_flags bevat. Kleine letters en cijfers, eventueel met - _ of . ertussen. De sleutel kan later niet worden gewijzigd.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Als een app of AI-agent je toestemming nodig heeft om namens je te handelen, kan die dat niet altijd vragen op het scherm dat je gebruikt. Daarom verschijnt het verzoek hier. Keur alleen verzoeken goed die je zelf hebt gestart en controleer of de code overeenkomt met die op het apparaat dat erom vraagt.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Als aan ALLE voorwaarden is voldaan, voert Radar de actie van deze regel uit en worden volgende regels niet meer beoordeeld. Deze regels worden na de toestemmings- en blokkeerlijsten en vóór de ingebouwde regels beoordeeld.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Waar Cbox ID mensen naartoe stuurt nadat ze zich bij deze app hebben afgemeld. De aangevraagde URI moet hier exact staan, inclusief een eventuele afsluitende schuine streep. Anders blijft de persoon op de afmeldpagina van Cbox ID. Laat dit leeg als de app nooit een terugverwijzing aanvraagt.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Waar je bent aangemeld, wat namens je kan handelen en wat er met je account is gebeurd. Als je een sessie niet herkent, meld je die af en wijzig je je wachtwoord.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Tijdens de overstap van een ander systeem kan je app het oude aanmeldendpoint in het manifest opgeven, naast de rollen. Het verschijnt hier ter goedkeuring voordat het wordt gebruikt.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Tijdens de overstap van een ander systeem kan een app vragen om e-mailadres en wachtwoord van personen die nog niet in Cbox ID staan, te controleren via het oude aanmeldendpoint. Test dat endpoint voordat je het goedkeurt. Een persoon die het accepteert, wordt hier aangemaakt en nooit meer teruggestuurd. Als het endpoint niet werkt, kunnen mensen die nog niet zijn overgestapt echter niet aanmelden.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Zonder rollen krijgt iedereen die kan aanmelden de rechten die een app aan gewone gebruikers geeft. Met rollen leg je één keer vast wie bijvoorbeeld bewerker is en wie bij ondersteuning hoort, zodat alle gekoppelde apps die indeling kunnen volgen.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Maak een regel die toegang toestaat, extra verificatie vraagt of blokkeert op basis van wat je over gebruikers weet. Vraag bijvoorbeeld extra verificatie bij aanmeldingen buiten de landen waar je actief bent, of zonder je kantoornetwerk uit van de regels voor aanmeldfrequentie.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Je handelt als deze persoon, in diens sessie en met diens toegangsrechten. De toegang is beperkt tot 30 minuten en alleen-lezen waar de console dat kan afdwingen. Elk verzoek wordt onder jouw naam vastgelegd.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Je verliest onmiddellijk de toegang. Als eigenaar kun je de organisatie pas verlaten als iemand anders eigenaar is. Draag eerst het eigendom over of verwijder de organisatie onder Instellingen.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Het eigen toegangsmodel van je app: resourcetypen zoals documenten en mappen, relaties zoals eigenaar, bewerker en lezer, en hoe die worden overgenomen. Lezers van een map kunnen bijvoorbeeld alle documenten erin lezen. Je app slaat de relaties tussen personen en resources op en vraagt bij elk verzoek: ‘mag deze gebruiker dit document bewerken?’. Het schema bepaalt het antwoord.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Het eigen toegangsmodel van je app: resourcetypen, de relaties per type en hoe die worden overgenomen. Je app schrijft tuples — wie welke relatie met wat heeft — en controleert de rechten bij elk verzoek.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Je app verstuurt deze gebeurtenissen met één aanroep per batch. Elke gebeurtenis vermeldt de organisatie waarin ze plaatsvond. Ze verschijnen hier en bij de eigen beheerders van die organisatie zodra ze binnenkomen.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'De standaardhuisstijl van je omgeving: uiterlijk, logo en favicon van de gehoste aanmelding, plus de naam en afzender die gebruikers zien. Elke organisatie neemt deze over, tenzij ze een eigen huisstijl instelt.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Je identiteitsprovider maakt, wijzigt en deactiveert hier automatisch personen via de SCIM-standaard. Wanneer iemand in je HR-systeem in of uit dienst gaat, bereikt de wijziging je apps binnen enkele seconden, zonder tickets of achtergebleven accounts — vooral bij vertrek is dat essentieel.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Je eigen aanmeldmethoden en actieve sessies. Een passkey biedt de sterkste bescherming en is het snelst in gebruik: je apparaat ontgrendelt deze met een vingerafdruk of gezichtsherkenning, zonder wachtwoord dat via phishing kan worden gestolen.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Je ontvanger behoudt hetzelfde geheim. Een hexadecimaal geheim van 64 tekens wordt whsec_ gevolgd door de base64-codering van die tekenreeks — "whsec_" + base64(secret). Een geheim dat al met whsec_ begint, wordt ongewijzigd gebruikt.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => ':part1 aanbevolen taken, ongeveer in deze volgorde. Elke taak wordt automatisch afgevinkt zodra deze daadwerkelijk is voltooid. Je hoeft niets handmatig als voltooid te markeren.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "de ID van de persoon",
  "org": "de organisatie namens welke de persoon handelt",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'Een API-sleutel (Organisatie-instellingen › API-sleutels), geen applicatiesleutel. Wordt versleuteld opgeslagen en nooit meer getoond.:part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Hoe mensen zich aanmelden bij :part1. Deze beginnen als de standaardomgeving; alles wat je hier verandert kan ze alleen maar strenger maken.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Zijn leden zijn uitgeschreven en alle :part1 is eigenaar van stoppen met het dienen van auth op het volgende verzoek. U kunt het hier reactiveren.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'De :part1 zijn uitgeschreven en alle :part2 die het bezit stopt met het serveren van auth op het volgende verzoek. U kunt het hier reactiveren.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'De bijbehorende :part1 kunnen niet meer aanmelden bij deze organisatie. Apps die erop vertrouwen, kunnen hen ook niet meer authenticeren. Onderliggende organisaties worden niet tegelijk opgeschort. Je kunt de organisatie hier opnieuw activeren.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minuten, ten hoogste :part1. Leeg maakt gebruik van de inzet :part2. Verkorten eindigt ook langere sessies die al lopen.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Alleen als uw app meer nodig heeft van :part1 dan inloggen wordt gescheiden door spaties. De eigen scopes van Sign-in worden altijd gevraagd.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Plakken het hele JSON-sleutelbestand van een serviceaccount toegewezen rollen / storage.objectCreator op de emmer. Versleuteld opgeslagen en nooit meer getoond.:part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Sandbox-omgevingen staan localhost-URL\'s toe en sturen nooit echte e-mail. :part1 blijft op het plan van dit project.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Meld je aan bij een van je apps als :part1 om te zien wat ze zien. De app wordt verteld dat jij het bent, en het auditlogboek van de organisatie registreert wie, wanneer en waarom.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'De app waarvan de aangegeven rollen en machtigingen tokens voor deze API dragen. Alleen apps die eigendom zijn van :part1 kunnen worden gekozen.',
    'the_new_key_for_part1_copy_it_now_you_won_t_be_able_to_42e3ecb3' => 'De nieuwe sleutel voor :part1. Kopieer deze nu; je kunt hem later niet meer bekijken.',
    'this_will_sign_people_out_of_part1_c2cac70c' => 'Hiermee worden mensen afgemeld bij :part1',
    'turn_off_part1_cdd28418' => ':part1 uitschakelen',
    'turn_off_part1_on_this_page_e3c91b07' => ':part1 op deze pagina uitschakelen',
    'turn_on_part1_41acb93f' => ':part1 inschakelen',
    'turn_on_part1_for_everyone_ef925d74' => ':part1 voor iedereen inschakelen',
    'until_part1_ca03d4b6' => 'tot :part1',
    'use_your_environment_s_defaults_for_part1_c214943d' => 'De standaardinstellingen van je omgeving gebruiken voor :part1?',
    'verify_part1_5e0158de' => ':part1 verifiëren',
    'view_part1_ac7c77ab' => ':part1 bekijken',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Wat een app mag doen bij deze API. Alleen de eigen apps van :part1 mogen deze rechten hebben.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Wat :part1 heeft inlog pagina biedt. Providers uit het omgeving worden geërfd; deze organisatie kan een uitschakelen, of het opzetten van een eigen op zijn plaats.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Wanneer de sleutel van een agent goedkeuring nodig heeft voor een actie, verschijnt het verzoek hier en op de telefoon van de persoon die de sleutel heeft gemaakt. Het wacht tot :part1.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Welke manieren in :part1 biedt naast een wachtwoord, en hoe lang een aanmelding duurt. Deze zijn hetzelfde voor elke organisatie in het.',
    'withdraw_access_for_part1_10961483' => 'Toegang van de app :part1 intrekken',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 De claim :part2 is iets anders: die geeft aan wat de :part3 :part4 mocht aanvragen, niet wat deze :part5 mag doen.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Ze worden niet gebruikt om bij deze console in te loggen: beheerders loggen via Cbox ID in op :part2, met de daar beschikbare inlogmethoden.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Vink de scope :part2 :part3 aan wanneer je de app registreert. Het ID-token bevat dan dezelfde rolnamen als claim :part4, de naam waar Kubernetes, Grafana en Vault naar zoeken. Je hoeft verder niets aan te maken.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Je neemt de identiteit van :part2 :part3 over voor ondersteuning. Alles wat je doet, wordt vastgelegd. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Een beheersleutel werkt alleen binnen de eigen omgeving. Exporteer de blauwdruk van deze app (GET /apps/{id}/blueprint) en registreer die met de sleutel van de andere omgeving (POST /apps met `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Een beheersleutel voor één agent. De agent kan alleen doen wat de scopes toestaan. De acties die je kiest, wachten op je goedkeuring, op je telefoon of op :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Een pagina op :part1. Laat dit leeg om in de console uit te komen, met :part2 vermeld op de uitnodiging.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Een :part1 is de IdP van één product. Deze bevat gescheiden :part2 :part3, productie en sandbox, elk met eigen gebruikers, sleutels en aanmeldingen, en wordt gefactureerd volgens een eigen abonnement.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Een machtiging bepaalt wat een :part1 na het inloggen mag doen. Wat een :part2 mag aanvragen, is een scope. Die stel je bij de registratie in onder :part3 :part4.',
    'a_workspace_key_reaches_the_workspace_itself_projects_e_28317ec8' => 'Een werkruimtesleutel geeft toegang tot de werkruimte zelf, met projecten, omgevingen, het team en sleutels, maar niet tot de inhoud van een omgeving. Maak er een aan onder :part1 :part2 :part3 op het hoofdniveau van het platform.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Toegangstokens voor deze app vermelden :part1 als hun audience :part2. Die API mag een token alleen accepteren als het die API als ontvanger noemt.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Toegangstokens voor deze app vermelden de issuer van deze omgeving,:part1 :part2, als hun audience. Dat verandert wanneer de app een scope van een van je geregistreerde API’s heeft.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Voeg op :part1 :part2 een TXT-record toe met de onderstaande waarde en klik op Verifiëren. Het kan enkele minuten duren voordat DNS-wijzigingen overal zijn doorgevoerd.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Een app registreert haar catalogus via de SDK.:part1 :part2 Je kunt de rol nu aanmaken en samenstellen zodra de sleutels binnenkomen.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Applicaties die deze omgeving vertrouwen als hun SAML-identiteitsprovider. Gebruik :part1 :part2 om mensen te laten inloggen met een account dat ze elders al hebben.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Goedkeuringen gelden voor de acties van de beheer-API. Deze scopes worden aangeboden via endpoints die nog geen acties zijn en worden daarom zonder goedkeuring uitgevoerd::part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Apps sturen mensen met :part1 naar de registratie en vragen een ingelogde persoon met :part2 om een organisatie aan te maken. Beide opties zijn alleen beschikbaar zolang dit is ingeschakeld.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Precies zoals je app de controle aanvraagt (:part1), met alle overerving die het schema definieert.',
    'auth_settings_differ' => ':count instelling wijkt af van je omgeving.|:count instellingen wijken af van je omgeving.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_fbee6c88' => 'Maak één keer verbinding op het hoofdniveau van het platform, in plaats van voor elke omgeving apart. Met jouw identiteit krijgt de verbinding toegang tot je werkruimte, alle omgevingen daarin die je beheert en je eigen account. Een omgevingstool gebruikt een argument :part1 :part2 en de REST-API een header :part3 om aan te geven waar de actie moet worden uitgevoerd. De verbinding kan doen wat jij kunt, binnen de grenzen die je toestaat. Elke kritieke actie wacht op je goedkeuring op je apparaat.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Elk nieuw account maakt een eigen organisatie aan en wordt daarvan eigenaar. Apps kunnen een ingelogde persoon ook vragen er een aan te maken met :part1 :part2.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Elke organisatie geeft de persoon één :part1, die bepaalt wat die daar mag beheren, en een willekeurig aantal :part2, die bepalen wat die binnen de apps mag doen.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Omgeving ‘:part1’ aangemaakt. Voeg :part2 toe via de domeininstellingen van de omgeving om het via DNS te verifiëren. Een niet-geverifieerd domein kan niet als issuer dienen.',
    'environments_nest_under_a_project_and_a_project_under_a_03ba63b6' => 'Omgevingen vallen onder een project en een project onder een :part1 :part2 :part3. Begin daar om alle onderdelen van een werkruimte te bekijken. Twee soorten rijen hebben hier nooit een werkruimte: :part4 is de omgeving waarin deze installatie zelf draait en waarin operators en de eigen mensen van werkruimtes zijn ondergebracht; een :part5 :part6 omgeving heeft geen project, wordt dus niet gefactureerd en is vanuit geen enkele werkruimte bereikbaar. Geen van beide is een fout die je op dit scherm moet herstellen. Je kunt ze hier ook niet opnieuw toewijzen.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Alle manieren waarop mensen inloggen op :part1, of ze ingeschakeld zijn en waar je ze wijzigt. Organisaties kunnen strengere regels instellen:part2 :part3.',
    'every_workspace_environment_and_operator_on_part1_a_sus_e4247a2d' => 'Elke werkruimte, omgeving en operator op :part1. Een opschorting, nieuwe omgeving of wijziging van een operator die je hier doorvoert, geldt voor allemaal.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Functievlag ‘:part1’ aangemaakt. Deze staat voor iedereen uit totdat een onderstaande regel of de standaardwaarde haar inschakelt.',
    'framework_3cf574caed49' => 'De scopes :value1 horen bij een geregistreerde API waarvoor deze client geen scopes mag hebben. Een client van een organisatie mag scopes hebben van de API’s van de eigen organisatie, en door tenants aan te vragen scopes van API’s die bij de omgeving horen.',
    'framework_43fd205dea6a' => 'De scope [:key] hoort al bij een andere API in deze omgeving. Scopesleutels zijn uniek per omgeving, omdat een tokenaanvraag een scope alleen met de sleutel aanduidt.',
    'framework_47867973811e' => 'Directorysynchronisatie met :provider mislukt: :request werd begrensd wegens te veel verzoeken (HTTP :status). Aantal pogingen: :attempt.',
    'framework_5eb368b0fb37' => 'Workday: de rapport-URL moet het webserviceadres van het rapport zijn: …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'De app [:clientId] moet dezelfde eigenaar hebben als de API waarvan zij de toegangsregels afdwingt. Door ze te koppelen zouden de rollen en machtigingen van de ene eigenaar in de tokens van de andere terechtkomen.',
    'framework_87da9891b0ad' => 'Directorysynchronisatie met :provider mislukt: :request was niet beschikbaar (HTTP :status) na :attempt pogingen.',
    'framework_98eb4683e38b' => 'Directorysynchronisatie met :provider mislukt: :request mislukt (HTTP :status): niet gevonden. Controleer het account, subdomein of rapportadres.',
    'framework_a934fd6a0c26' => '[:origin] gebruikt http. Daardoor zouden de sleutel en alles wat de pagina ermee doet onversleuteld over het netwerk gaan. Gebruik https, of tijdens het ontwikkelen een loopbackhost zoals http://localhost:3000.',
    'framework_b63785ee57fb' => 'Directorysynchronisatie met :provider mislukt: :request mislukt (HTTP :status): de inloggegevens geven geen toestemming om werknemers te lezen.',
    'framework_e5ca82ab9dff' => 'Directorysynchronisatie met :provider mislukt: :request mislukt (HTTP :status): de inloggegevens zijn geweigerd.',
    'framework_fc1964a8e8c4' => 'Dit is het laatste actieve geheim van client [:clientId]. Roteer het geheim om het te vervangen. Als je het intrekt, kan de client zich niet meer authenticeren.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Als dat endpoint :part1 is, kunnen mensen die nog niet zijn gemigreerd niet inloggen. Voor iedereen die al is overgezet, verandert er niets.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'In de volgorde waarin mensen ze zien. Als je hier een methode van de omgeving uitschakelt, verdwijnt alleen de knop van deze pagina. Mensen kunnen er elders nog steeds mee inloggen. Maak SSO verplicht op :part1 :part2 om je identiteitsprovider de enige inlogmethode te maken.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Sleutels beginnen met dit voorvoegsel, zodat een sleutel in een logboek aan deze app kan worden gekoppeld: :part1 :part2. 2–16 kleine letters of cijfers, gevolgd door :part3 of :part4 :part5, uniek in deze omgeving. Door een voorvoegsel in te stellen schakel je sleutels in. Door het te wissen voorkom je nieuwe sleutels; bestaande sleutels blijven werken totdat ze worden ingetrokken.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Functievlaggen met hun doelgroepregels opvragen en elke vlag beoordelen voor een gebruiker in een organisatie. Dat vraagt de backend van een app wanneer er geen token beschikbaar is.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Directory’s (SCIM, Google Workspace, Microsoft Entra) opvragen die personen synchroniseren, met hun groepen en synchronisatiefouten. Bearertokens en inloggegevens van providers worden nooit getoond.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'SAML- en OIDC-verbindingen opvragen waarmee organisaties aanmelden, en de e-maildomeinen die mensen ernaartoe leiden. Certificaten, clientgeheimen en ondertekeningssleutels worden nooit getoond.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Externe providers opvragen waaraan mensen hun accounts kunnen koppelen, welke apps hun tokens tijdelijk mogen gebruiken en wie een account heeft gekoppeld. Clientgeheimen en tokens worden nooit getoond.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Eenmalige links naar het beheerdersportaal aanmaken en intrekken. Daarmee kan de IT-beheerder van een organisatie zonder account SSO, domeinen of directorysynchronisatie instellen. Een nieuwe link wordt maar één keer getoond.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Er zijn nog geen rollen om aan te koppelen. Definieer er een onder :part1 :part2 of laat een app haar eigen rollen declareren.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_462fe672' => 'Niemand in deze organisatie heeft een sleutel voor een van haar apps aangemaakt. Gebruikers maken hun eigen sleutels onder Mijn account aan voor een app die API-sleutels voor leden in de instellingen heeft ingeschakeld: :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Niemand is bij een app ingelogd als een van de mensen daarin. Start een sessie vanaf de pagina van een persoon onder :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Alleen de console kan een app :part1 geven, niet een beheersleutel of een agent die namens jou handelt. Ken dit toe in de console, op de pagina Scopes van de app.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Alleen acties die je zelf in :part1 mag uitvoeren, zijn beschikbaar. Als je later een machtiging verliest, verliest de sleutel die ook.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Voegt de sleutels van de functievlaggen die voor de persoon zijn ingeschakeld in de organisatie waarbij die is aangemeld, als claim `feature_flags` toe aan het toegangstoken, het ID-token en UserInfo.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Voegt de ROLLEN van de persoon onder de naam `groups` toe aan het ID-token. Die naam verwachten Kubernetes, Grafana, Vault en veel oudere SaaS-apps. In deze console bestaat geen object met de naam groep. Maak een rol met de naam die de app verwacht; die wordt dan in dit veld opgenomen.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Radars modus, ingebouwde en eigen regels, toestemmings- en blokkeerlijsten en de beslissingsweergave lezen: waarom een aanmelding of registratie is toegestaan, extra verificatie vereiste of is geblokkeerd. IP- en e-mailadressen uit een beslissing worden nooit getoond.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'De auditgebeurtenissen die je app heeft verstuurd en de exports ervan lezen, de gebeurtenisketen van een organisatie controleren en de bijbehorende schema’s en bewaartermijnen bekijken.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Het autorisatieschema en de tuples lezen en rechtencontroles en lijstquery’s uitvoeren, zoals ‘mag deze gebruiker dit document bewerken?’ of ‘welke documenten mag deze persoon zien?’. Alleen de rechten die de backend van een app nodig heeft om toegang te controleren.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Vervang het autorisatieschema: de resourcetypen en hoe elke relatie wordt bepaald. Dit verandert direct het antwoord op elke controle in deze omgeving.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Rollen die in de hele omgeving gelden, in elke organisatie en ook voor mensen die tot geen enkele organisatie behoren. Organisaties zien deze nooit.:part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Sandboxomgeving, uitsluitend voor tests. Dit is :part1 je productieaanmelding en er worden geen echte e-mails verstuurd.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Scope ‘:part1’ verwijderd. Apps die deze hadden, behouden de scope als ingevoerde scope, die geen toegang meer geeft tot deze API.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'De eerste :part1 worden getoond. Zoek om de rest te vinden. Alles wat je al hebt aangevinkt, blijft in de lijst staan.',
    'sms_allowed_country_count' => 'Geaccepteerd als tweede factor in :count land.|Geaccepteerd als tweede factor in :count landen.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Iemand die :part1 wordt nooit doorgestuurd. Diens wachtwoord is het wachtwoord in Cbox ID en het oude systeem heeft daar niets over te zeggen.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Van iemand die inlogt en :part1 is, worden het e-mailadres en wachtwoord naar dat endpoint gestuurd. Als het antwoord positief is, wordt de persoon hier aangemaakt en nooit meer doorgestuurd.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Inloggegevens voor externe diensten opslaan, roteren en intrekken, en een app toestemming geven of ontnemen om ze tijdelijk te gebruiken. Dit gaat niet over de scopes vault.manage / vault.lease in het eigen token van een app.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Elk verzoek bevat :part1 :part2, een beheersleutel van deze omgeving.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Loop je op een van deze punten vast? Elke pagina in de console heeft een :part1 :part2 :part3 naast de titel, met een korte uitleg en een link naar de volledige handleiding.',
    'suspension_is_the_only_lever_here_and_it_is_reversible_84455a59' => 'Hier kun je een werkruimte alleen opschorten of opnieuw activeren. Niets op deze pagina verwijdert een werkruimte of wist de gegevens ervan. De installatie bevat ook omgevingen zonder werkruimte: de hoofdomgeving van het platform en eventuele overgebleven niet-gekoppelde omgevingen. Beide zijn duidelijk aangeduid onder :part1 :part2.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Deze pagina verandert alleen de opschorting, die ongedaan kan worden gemaakt. Een omgeving selecteren en openen verandert alleen wat de console toont. Geen van beide omgevingen wordt gewijzigd.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'Sms-codes naar :part1 werken niet meer. De authenticator-app, passkeys en herstelcodes blijven ongewijzigd. Als het telefoonnummer de enige tweede factor was, wordt het account alleen door het wachtwoord beschermd totdat een nieuwe factor is ingesteld.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Dat certificaat is al verlopen (:part1). Download het huidige certificaat van je identiteitsprovider.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Deze favicon kan niet worden gebruikt. Stuur de afbeelding zelf als een base64-gecodeerde data:-URI (data:image/png;base64,…). Externe afbeeldings-URL’s worden niet geaccepteerd. Elke bezoeker haalt de afbeelding op de aanmeldpagina op, waardoor een externe server informatie over die bezoekers zou ontvangen.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Er zijn veel e-mails verstuurd. Probeer het over :part1 seconden opnieuw of controleer ondertussen je spammap.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Alle punten op de lijst zijn nu afgerond. Voortaan kom je vooral terug in de console wanneer dat nodig is. Twee onderdelen verdienen een regelmatige controle: :part1 :part2 :part3 en :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Dit logo kan niet worden gebruikt. Stuur de afbeelding zelf als een base64-gecodeerde data:-URI (data:image/png;base64,…). Externe afbeeldings-URL’s worden niet geaccepteerd. Elke bezoeker haalt de afbeelding op de aanmeldpagina op, waardoor een externe server informatie over die bezoekers zou ontvangen.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'De e-maildomeinen waarop je organisaties aanspraak hebben gemaakt. Een geverifieerd domein stuurt iedereen met een adres op dat domein naar de verbinding van de organisatie: :part1 :part2. Elk domein wordt op de pagina van de organisatie geverifieerd.',
    'the_metadata_value_for_part1_must_be_text_63748730' => 'De metadatawaarde voor [:part1] moet tekst zijn.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'De nieuwste vermeldingen in de geschiedenis van :part1.',
    'the_people_in_part1_cf74b32e' => 'De mensen in :part1.',
    'the_people_on_part1_and_what_each_may_reach_474ab0a4' => 'De mensen in :part1 en waar ieder toegang toe heeft.',
    'the_platform_s_own_environment_on_part1_how_every_works_07c8a7ac' => 'De eigen omgeving van het platform op :part1: hier melden alle werkruimte-eigenaren en operators aan bij Cbox ID en vindt de aanmelding voor alle omgevingsconsoles plaats. Een wijziging geldt voor al deze aanmeldingen.',
    'the_role_part1_belongs_to_one_organization_and_cannot_b_e2bba059' => 'De rol [:part1] hoort bij één organisatie en kan niet overal worden toegekend.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'De rol [:part1] kan niet in deze organisatie worden toegekend. Deze hoort bij een andere organisatie of bij een app die deze organisatie niet mag gebruiken.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Dezelfde code, stap voor stap, met afmelden::part1 :part2 .',
    'the_scim_base_url_must_be_a_public_address_part1_4cfd762c' => 'De SCIM-basis-URL moet een openbaar adres zijn. (:part1)',
    'the_secret_was_shown_once_when_the_app_was_created_part_7a1fcce3' => 'Het geheim is één keer getoond, toen de app werd aangemaakt.:part1 :part2 :part3 voor een nieuw geheim.',
    'the_whole_environment_part1_6c96bfa7' => 'De hele omgeving :part1',
    'theme_this_organization_s_sign_in_page_its_team_signs_i_cceda878' => 'Pas de aanmeldpagina van deze organisatie aan. Het team meldt aan op :part1 :part2 .',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'Er is geen clientgeheim om te plakken. :part1 verwacht een ondertekende assertion, die we voor elke aanmelding met de bovenstaande sleutel maken en ruim voor het verlopen vernieuwen.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Er is nog geen rol om toe te kennen. Definieer er een op de pagina :part1 :part2 :part3 of laat een app haar eigen rollen in het manifest declareren.',
    'these_apply_to_every_organization_in_part1_not_only_par_ac56590d' => 'Deze gelden voor elke organisatie in :part1, niet alleen :part2 .',
    'these_are_its_own_credentials_for_that_environment_s_co_a68e7d01' => 'Dit zijn de eigen inloggegevens voor de configuratie van die omgeving. :part1',
    'these_are_the_buttons_on_part1_how_every_workspace_owne_5c0655c0' => 'Dit zijn de knoppen op :part1 waarmee werkruimte-eigenaren en operators aanmelden bij Cbox ID en daarmee bij de consoles van alle omgevingen. De beheerders daarvan gebruiken Cbox ID-accounts. Registreer de getoonde omleidings-URI bij elke provider. Je vindt deze onder :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Deze knoppen zijn voor de mensen die bij je apps inloggen, op de inlogpagina’s van :part1 :part2. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Die persoon wordt eigenaar van :part1 en jij wordt beheerder. Alleen de nieuwe eigenaar kan het eigendom teruggeven.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Deze app heeft scopes van meerdere API’s: :part1 :part2. Een token is steeds voor één API bedoeld, dus de app noemt de gewenste API met de parameter :part3. Een verzoek om scopes van twee API’s tegelijk wordt geweigerd.',
    'this_console_is_your_workspace_its_projects_team_keys_a_66180b31' => 'Deze console is je werkruimte, met projecten, team, sleutels en facturering. Hoe mensen aanmelden bij je apps, waaronder :part1, stel je per omgeving in de eigen console van die omgeving in.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Dit toegangsmiddel vereist goedkeuring van een persoon voor deze actie, maar er is geen persoon geregistreerd die die kan geven. Voer de actie uit vanuit de console of maak daar een sleutel aan zodat de eigenaar kan goedkeuren.',
